  {
    "type": "function",
    "name": "get_source_claims",
    "description": "Drill-down unter ein Umwelt-Item: liefert Ledger-Claims, soweit ein Ledger geladen ist, sonst die Claim-IDs.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
    "type": "function",
    "name": "find_related_items",
    "description": "Findet andere Umwelt-Items mit gemeinsamen sourceClaimIds oder sourceArtifactItemIds.",
    "parameters": {
      "type": "object",
      "properties": {
        "itemId": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 20
        }
      },
      "required": [
        "itemId"
      ]
    }
  },
  {
